{
	struct pipe_inode_info *pipe = filp->private_data;
	int count, head, tail, mask;

	switch (cmd) {
		case FIONREAD:
			__pipe_lock(pipe);
			count = 0;
			head = pipe->head;
			tail = pipe->tail;
			mask = pipe->ring_size - 1;

			while (tail != head) {
				count += pipe->bufs[tail & mask].len;
				tail++;
			}
			__pipe_unlock(pipe);

			return put_user(count, (int __user *)arg);
